"""Report how a generated project differs from what pytemplate wrote.

``status`` is read-only: it compares the files on disk with the SHA-256 inventory recorded in
``.pytemplate.toml`` and never merges, rewrites, or deletes anything.
"""

from __future__ import annotations

import hashlib
import os
import tomllib
from dataclasses import dataclass
from pathlib import Path, PurePosixPath

from pytemplate.errors import RequestError

MANIFEST_FILE = ".pytemplate.toml"

# Directories that never hold generated files, and files that change without the user editing
# generated code (the lock file is created by `uv lock`, the manifest describes itself).
IGNORED_DIRECTORIES = frozenset(
    {
        ".git",
        ".venv",
        "__pycache__",
        ".pytest_cache",
        ".mypy_cache",
        ".ruff_cache",
        ".tox",
        ".nox",
        "node_modules",
        ".hypothesis",
    }
)
IGNORED_FILES = frozenset({"uv.lock", MANIFEST_FILE, ".DS_Store"})


class StatusError(RequestError):
    """Raised when a directory has no readable pytemplate manifest (CLI exit code 1)."""


@dataclass(frozen=True)
class StatusReport:
    """Files changed, deleted, and added since the project was generated."""

    project_path: Path
    changed: tuple[str, ...]
    deleted: tuple[str, ...]
    added: tuple[str, ...]

    @property
    def clean(self) -> bool:
        """Return whether the project still matches what was generated."""
        return not (self.changed or self.deleted or self.added)

    def as_dict(self) -> dict[str, object]:
        """Return the report in the shape printed by ``status --json``."""
        return {
            "ok": True,
            "project_path": str(self.project_path),
            "clean": self.clean,
            "changed": list(self.changed),
            "deleted": list(self.deleted),
            "added": list(self.added),
        }


def _recorded_files(project_path: Path) -> dict[str, str]:
    """Return ``{relative path: sha256}`` from the manifest, or raise ``StatusError``."""
    manifest = project_path / MANIFEST_FILE
    if not project_path.is_dir():
        raise StatusError(f"Not a directory: {project_path}")
    if not manifest.is_file():
        raise StatusError(
            f"No {MANIFEST_FILE} in {project_path}; it was not generated by pytemplate-uv "
            "3.1 or later."
        )
    try:
        data = tomllib.loads(manifest.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        raise StatusError(f"Cannot read {manifest}: {error}") from error
    entries = data.get("files")
    if not isinstance(entries, list):
        raise StatusError(f"{manifest} has no [[files]] inventory to compare against.")
    recorded: dict[str, str] = {}
    for entry in entries:
        path = entry.get("path") if isinstance(entry, dict) else None
        digest = entry.get("sha256") if isinstance(entry, dict) else None
        if not isinstance(path, str) or not isinstance(digest, str):
            raise StatusError(f"{manifest} has a [[files]] entry without a path and sha256.")
        parts = PurePosixPath(path)
        if parts.is_absolute() or ".." in parts.parts:
            raise StatusError(f"{manifest} lists a path outside the project: {path}")
        recorded[path] = digest
    return recorded


def _present_files(project_path: Path) -> set[str]:
    """Return every non-ignored regular file below the project, as POSIX relative paths."""
    found: set[str] = set()
    for directory, names, files in os.walk(project_path):
        names[:] = [name for name in names if name not in IGNORED_DIRECTORIES]
        for name in files:
            if name in IGNORED_FILES or name.endswith(".pyc"):
                continue
            path = Path(directory, name)
            found.add(path.relative_to(project_path).as_posix())
    return found


def _digest(path: Path) -> str | None:
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError:
        return None


def project_status(project_path: Path) -> StatusReport:
    """Compare a generated project with its manifest without changing anything."""
    project_path = project_path.expanduser().resolve()
    recorded = {
        path: digest
        for path, digest in _recorded_files(project_path).items()
        if PurePosixPath(path).name not in IGNORED_FILES
        and not IGNORED_DIRECTORIES.intersection(PurePosixPath(path).parts)
    }
    present = _present_files(project_path)
    changed: list[str] = []
    deleted: list[str] = []
    for path, digest in sorted(recorded.items()):
        target = project_path / path
        if not target.is_file():
            deleted.append(path)
        elif _digest(target) != digest:
            changed.append(path)
    added = sorted(present - set(recorded))
    return StatusReport(project_path, tuple(changed), tuple(deleted), tuple(added))
